(2, 7, 'IP privat dipakai…', '["Hanya di dalam jaringan lokal","Langsung di internet","Hanya di satelit","Hanya di server cloud"]'::jsonb, 0, 'IP privat tidak bisa diakses langsung dari internet.'),
(2, 8, 'IP yang tidak berubah disebut…', '["IP dinamis","IP statis","IP sementara","IP acak"]'::jsonb, 1, 'IP statis tetap.'),
(2, 9, 'IP yang diganti secara berkala oleh ISP adalah…', '["IP statis","IP dinamis","IP privat","IP manual"]'::jsonb, 1, 'IP dinamis berubah berkala.'),
(2, 10, 'Prefix /24 setara dengan subnet mask…', '["255.0.0.0","255.255.0.0","255.255.255.0","255.255.255.255"]'::jsonb, 2, '24 bit pertama bernilai 1 sehingga 255.255.255.0.'),
(3, 1, 'Topologi yang semua perangkatnya terhubung ke satu kabel utama adalah…', '["Star","Bus","Ring","Mesh"]'::jsonb, 1, 'Itu ciri topologi bus.'),
(3, 2, 'Pada topologi ring, setiap perangkat terhubung ke…', '["Satu kabel utama","Dua perangkat di sampingnya","Semua perangkat","Satu switch pusat"]'::jsonb, 1, 'Perangkat membentuk lingkaran.'),
