(3, 5, 'Topologi yang menggabungkan beberapa star secara bertingkat adalah…', '["Tree","Bus","Ring","Ad hoc"]'::jsonb, 0, 'Tree adalah gabungan star bertingkat.'),
(3, 6, 'Topologi dengan banyak jalur cadangan dan paling andal adalah…', '["Bus","Mesh","Ring","Star"]'::jsonb, 1, 'Mesh punya banyak jalur alternatif.'),
(3, 7, 'Berapa kabel untuk mesh penuh 4 perangkat?', '["4","6","8","12"]'::jsonb, 1, '4 x 3 / 2 = 6.'),
(3, 8, 'Topologi hybrid adalah…', '["Gabungan dua atau lebih jenis topologi","Topologi tanpa kabel","Topologi satu perangkat","Nama lain bus"]'::jsonb, 0, 'Hybrid menggabungkan beberapa topologi.'),
